/**
 * The demo bundle, generated by `scripts/build-web-data.sh`.
 *
 * `docs/09`: "Every displayed number comes from a retained fixture or an
 * actual transaction-derived record." Loading a static bundle enforces
 * that structurally -- the demo produced the file, or the screen has
 * nothing to render. There is no code path where the interface computes a
 * figure the engine never returned.
 */

export interface Assessment {
  assessment_id: string;
  binding_key: string;
  input_hash: string;
  model_hash: string;
  policy_hash: string;
  assessment_kind: string;
  decision: string;
  risk_permission: string | null;
  sequence: number;
  assessment_hash: string;
  created_at: number;
  /** The full canonical assessment the engine returned. */
  payload: AssessmentPayload;
}

export interface AssessmentPayload {
  assessment_id: string;
  assessment_time: number;
  authorization_class: string;
  input_hash: string;
  model_hash: string;
  policy_hash: string;
  schema_version: string;
  sequence: number;
  /**
   * Engine reasons: a unit variant is a string, a variant carrying data
   * is a single-key object. Typed as `string[]` until 15 September, which
   * rendered every structured reason as `[object Object]`.
   */
  reasons: Reason[];
  omitted_evidence: string[];
  synthetic_used?: boolean;
  outcome: Outcome;
  stress_results?: StressResult[];
}

export interface Outcome {
  decision: string;
  requested_principal?: string;
  approved_principal?: string;
  capacity?: Capacity;
  terms?: Terms;
}

export interface Capacity {
  agent_capacity: string;
  agent_binding: string;
  drawable_capacity: string;
  drawable_binding: string;
  score: number | null;
}

export interface Terms {
  approved_principal: string;
  apr_bps: number;
  term_seconds: number;
  required_equity: string;
  price_breakdown?: PriceBreakdown;
  economics?: Record<string, string | number>;
}

export interface PriceBreakdown {
  apr_bps: number;
  base_rate_bps: number;
  clamped: boolean;
  history_discount_bps: number;
  portfolio_surcharge_bps: number;
}

export interface StressResult {
  applied_price_shock_bps?: number;
  [k: string]: unknown;
}

/** One check `credence-verify` ran against the live deployment. */
export interface Check {
  beat: string;
  name: string;
  passed: boolean;
  /** Verbatim, because it holds the revert selector. */
  detail: string;
}

/** A probability committed BEFORE the loan was funded (`docs/06`). */
export interface Forecast {
  forecast_id: string;
  binding_key: string;
  committed_at: number;
  event_definition: string;
  horizon_seconds: number;
  probability_ppm: number;
  payload?: Record<string, unknown>;
}

/** How a forecast actually resolved. */
export interface ForecastOutcome {
  forecast_id: string;
  outcome_id: string;
  resolution: string;
  resolved_at: number;
  brier_ppm: number;
}

import type { Reason } from "./reasons";

/** One evidence item as the engine received it (`docs/04`). */
export interface Evidence {
  evidence_id: string;
  source: string;
  origin: string;
  requirement: string;
  state: string;
  coverage: string;
  observed_at: number;
  retrieved_at: number;
  content_hash: string;
  scenario_id: string | null;
  value?: unknown;
}

/** The snapshot the engine hashed, item by item. */
export interface Snapshot {
  assessment_time: number;
  account?: Evidence;
  market?: Evidence;
  history?: Evidence;
  forecasts?: Evidence;
  portfolio?: Evidence;
  [k: string]: unknown;
}

export interface Run {
  name: string;
  /** Present when the run recorded on-chain checks. */
  checks?: Check[];
  assessments: Assessment[];
  /** Keyed by input_hash, so an assessment pairs with its exact snapshot. */
  snapshots: Record<string, Snapshot>;
  outcomes: ForecastOutcome[];
  forecasts: Forecast[];
  chain_events: unknown[];
}

/**
 * What the demo bundle was built from, and where it was deployed.
 *
 * `deployment` stays a loose record for the fields nothing reads, but
 * the ones the interface DISPLAYS are typed: a chain id rendered as
 * `undefined` in the page chrome would be a provenance claim the bundle
 * never made.
 */
export interface Manifest {
  runs: { name: string; assessments: number; snapshots: number }[];
  generated_from: string[];
  deployment?: {
    chain_id?: number;
    deployment_id?: number;
    addresses?: Record<string, string>;
    erc8004?: { agent_id?: number };
    [key: string]: unknown;
  };
}

/** One agent profile in `docs/09` beat 1's comparison. */
export interface Profile {
  name: string;
  blurb: string;
  assessment: AssessmentPayload;
}

export interface Comparison {
  policy_hash: string;
  model_hash: string;
  profiles: Profile[];
}

/**
 * A loan as the Envio indexer reconstructed it, from events alone.
 *
 * Every amount is a STRING. These are uint256 base units and JSON numbers
 * are doubles: a realistic principal loses precision silently on the way
 * through, which is the one kind of error a ledger screen must not make.
 * `units()` takes strings for the same reason.
 */
export interface IndexedLoan {
  id: string;
  chainId: number;
  loanId: string;
  account: string;
  principal: string;
  status: string;
  principalRepaid: string;
  interestCollected: string;
  principalLoss: string;
  unpaidInterest: string;
  originatedAt: string;
  /** Null until recovery opens, and for a loan that repaid normally. */
  recoveryOpenedAt: string | null;
  resolvedAt: string | null;
  heldSeconds: string | null;
}

/** One lifecycle event, exactly as the log carried it. */
export interface IndexedEvent {
  id: string;
  loan_id: string;
  chainId: number;
  kind: string;
  blockNumber: string;
  blockTimestamp: string;
  logIndex: number;
  txHash: string;
  principal: string | null;
  interest: string | null;
  principalLoss: string | null;
  unpaidInterest: string | null;
}

/** One orderbook level, in the venue's scaled integers. */
export interface PerplLevel {
  price: number;
  size: number;
}

/**
 * Recent perpetual funding.
 *
 * NOT the engine's `funding_rate_bps`, which is the lender's cost of
 * capital. This is the premium longs pay shorts to hold a perp near its
 * index -- a positioning signal, displayed and never fed to the engine.
 */
export interface PerplFunding {
  samples: number;
  latest_bps: number;
  mean_bps: number;
  max_abs_bps: number;
  /** Share of NON-ZERO samples agreeing with the window's direction. */
  one_sided_pct: number;
  window_seconds: number;
  observed_at: number;
}

export interface PerplBook {
  price_decimals: number;
  size_decimals: number;
  bids: PerplLevel[];
  asks: PerplLevel[];
  /** The WHOLE book's level count, not the visible rows. */
  bid_levels: number;
  ask_levels: number;
}

export interface PerplMarket {
  observed_at: number;
  realized_volatility_bps: number;
  volatility_window_seconds: number;
  liquidity_depth: string;
}

export interface Perpl {
  captured_at: number;
  venue: {
    base_url: string;
    market_id: number;
    symbol: string;
    resolution_seconds: number;
    window_seconds: number;
  };
  market: PerplMarket;
  funding: PerplFunding;
  book: PerplBook;
  /** The retained snapshot with observed market evidence substituted. */
  snapshot: unknown;
  /** The same snapshot with its declared market evidence, same clock. */
  baseline: unknown;
  baseline_market: PerplMarket;
  snapshot_source: string;
}

/**
 * One agent of the cohort, with its own credit account and its own record.
 *
 * `demo-cohort.sh` drives several accounts against ONE facility, which is
 * the only run in the bundle where more than one agent borrows. Kept
 * apart from `Run` because the shape differs: a run is one account over
 * time, a cohort is several accounts at one time, and pooling them would
 * merge four histories into a fifth agent that never existed.
 */
export interface CohortAgent {
  name: string;
  /** The `CreditAccount` this agent borrowed through, on chain. */
  account: string;
  assessments: Assessment[];
  snapshots: Record<string, Snapshot>;
}

export interface Cohort {
  agents: CohortAgent[];
}

export interface Indexed {
  loans: IndexedLoan[];
  events: IndexedEvent[];
}

const cache = new Map<string, unknown>();

async function fetchJSON<T>(path: string): Promise<T> {
  const hit = cache.get(path);
  if (hit) return hit as T;
  const res = await fetch(path);
  if (!res.ok) {
    // A missing bundle is a missing demo run, not an empty one. Say which,
    // because the fix is to run the script rather than to debug the page.
    throw new Error(
      `${path} is not available (${res.status}). ` +
        `Generate the bundle with: pnpm data`,
    );
  }
  const body = (await res.json()) as T;
  cache.set(path, body);
  return body;
}

export const loadManifest = () => fetchJSON<Manifest>("data/manifest.json");
export const loadRun = (name: string) => fetchJSON<Run>(`data/${name}.json`);
/**
 * The policy a given run actually hashed.
 *
 * Per run, not one shared file. `demo-monitor.sh` runs on a gateway
 * template whose `base_history_cap` is 10e9 while the shipped policy is
 * 6.2e9, and the engine refuses a declared policy hash that is not the
 * content hash of the policy it was handed. Loading the wrong one made a
 * CLEAN replay return `Unavailable` -- a DIFFERENCE, which would have made
 * the replay screen prove the opposite of what it claims.
 */
export const loadComparison = () =>
  fetchJSON<Comparison>("data/comparison.json");

export const loadPolicy = (run: string) =>
  fetchJSON<unknown>(`data/${run}-policy.json`);

/**
 * What the Envio indexer stored, written by
 * `scripts/build-indexed-data.sh`.
 *
 * Absent when the indexer has not been run. That is a different state
 * from "a chain with no loans", and the screen says so rather than
 * rendering an empty lifecycle.
 */
export const loadIndexed = () => fetchJSON<Indexed>("data/indexed.json");

/**
 * Live Perpl market data, captured by `credence-perplpanel`.
 *
 * Absent until the capture is run. That is a different state from "the
 * venue reported nothing", and the screen says so rather than rendering
 * an empty book that reads like a dead market.
 */
export const loadPerpl = () => fetchJSON<Perpl>("data/perpl.json");

/**
 * The multi-agent cohort, written by `scripts/demo-cohort.sh`.
 *
 * Absent until that demo is run. That is a different state from "a
 * facility with one borrower", and the globe says which rather than
 * quietly rendering a market of one.
 */
export const loadCohort = () => fetchJSON<Cohort>("data/cohort.json");

/** Base units to a readable decimal. Never rounds a displayed amount. */
export function units(raw: string | number | undefined, decimals = 6): string {
  if (raw === undefined) return "-";
  const s = String(raw);
  if (!/^\d+$/.test(s)) return s;
  const pad = s.padStart(decimals + 1, "0");
  const whole = pad.slice(0, pad.length - decimals);
  const frac = pad.slice(pad.length - decimals).replace(/0+$/, "");
  return frac ? `${Number(whole).toLocaleString()}.${frac}` : Number(whole).toLocaleString();
}

/**
 * The scale of the held asset, read from the check's own detail.
 *
 * `credence-verify` emits "<amount> base units of <address> at <n>
 * decimals". This screen used to hardcode 18 while `Lender.tsx` defaulted
 * to 6 for the identical format, so the two disagreed about the same
 * string -- and the account holds SETTLEMENT (6) in the common case,
 * which made the headline figure understated by 10^12. The committed
 * fixture happened to hold the risky token, which is 18, so it looked
 * right.
 *
 * Falls back to 6 rather than 18: settlement is what the first branch of
 * the verifier reads, so an older record with no decimals is far more
 * likely to be denominated in it.
 */
export function heldDecimals(detail: string): number {
  const match = detail.match(/at (\d+) decimals/);
  return match ? Number(match[1]) : 6;
}

export const bps = (v: number | undefined): string =>
  v === undefined ? "-" : `${(v / 100).toFixed(2)}%`;
